import os, json, time, math
import numpy as np
try:
    from scipy.optimize import minimize, nnls
except Exception:
    minimize = None; nnls = None

# Try to import lineage utilities
import sys
sys.path.append('storage/noesis')
try:
    from analyze_contacts import active_sets as ac_active_sets
except Exception:
    ac_active_sets = None
try:
    from operators_integration import polish_preserving_boundary
except Exception:
    polish_preserving_boundary = None

N = 26
R_MIN = 1e-6
SAFETY = 1e-9
TOL_EQ = 1e-8

P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
P_CONS = 'storage/noesis/nmap/consensus_n26_tol1e8.json'
LOG_PATH = 'storage/noesis/exports/tangent_step_attempt_v1.json'

# ------------- Helpers -------------
def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N, 2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    assert c.shape == (N,2) and r.shape == (N,) and np.all(r > 0)
    return c, r

def pack_to_z(c, r):
    Z = np.zeros((N,3), dtype=float)
    Z[:, :2] = c; Z[:, 2] = r
    return Z.ravel()

def z_to_pack(z):
    Z = np.asarray(z, float).reshape(N,3)
    return Z[:, :2], Z[:, 2]

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    s_pairs = dist - (r[:,None] + r[None,:])
    return (s_xL, s_xR, s_yB, s_yT), s_pairs

def boundary_mask(c, r, tol):
    (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
    return (s_xL <= tol) | (s_xR <= tol) | (s_yB <= tol) | (s_yT <= tol)

def grad_row_boundary(i, kind, n=N):
    row = np.zeros(3*n, dtype=float)
    xi = 3*i; yi = xi + 1; ri = xi + 2
    if kind in ('xL','x_min'):
        row[xi] = 1.0;  row[ri] = -1.0
    elif kind in ('xR','x_max'):
        row[xi] = -1.0; row[ri] = -1.0
    elif kind in ('yB','y_min'):
        row[yi] = 1.0;  row[ri] = -1.0
    elif kind in ('yT','y_max'):
        row[yi] = -1.0; row[ri] = -1.0
    return row

def grad_row_pair(c, i, j, n=N):
    row = np.zeros(3*n, dtype=float)
    xi = 3*i; yi = xi + 1; ri = xi + 2
    xj = 3*j; yj = xj + 1; rj = xj + 2
    dx = c[i,0] - c[j,0]; dy = c[i,1] - c[j,1]
    d = float(np.hypot(dx, dy))
    if d > 1e-15:
        invd = 1.0/d
        row[xi] = dx*invd; row[yi] = dy*invd
        row[xj] = -dx*invd; row[yj] = -dy*invd
    row[ri] = -1.0; row[rj] = -1.0
    return row

def build_Aeq_boundary(c, r, tol=TOL_EQ):
    if ac_active_sets is not None:
        b_act, _ = ac_active_sets(c, r, tol=tol)
    else:
        # fallback: derive from slacks directly
        (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
        b_act = []
        for i in range(N):
            if s_xL[i] <= tol: b_act.append((i,'xL', float(s_xL[i])))
            if s_xR[i] <= tol: b_act.append((i,'xR', float(s_xR[i])))
            if s_yB[i] <= tol: b_act.append((i,'yB', float(s_yB[i])))
            if s_yT[i] <= tol: b_act.append((i,'yT', float(s_yT[i])))
    rows = []
    for (i, kind, *_) in b_act:
        rows.append(grad_row_boundary(int(i), str(kind)))
    if not rows:
        return np.zeros((0, 3*N), dtype=float)
    A = np.vstack(rows)
    # Optional column scaling to balance x,y vs r magnitude
    scale = np.ones(3*N, dtype=float)
    scale[2::3] = 1.0  # radii columns
    # centers similar magnitude; keep uniform scaling = 1
    A_scaled = A / scale
    return A_scaled

def nullspace(A, rtol=1e-10):
    # Return an orthonormal basis Q for null(A): shape (3N, k)
    if A.size == 0:
        return np.eye(3*N)
    U, S, Vh = np.linalg.svd(A, full_matrices=True)
    rank = int(np.sum(S > (rtol * S.max() if S.size else 0.0)))
    Q = Vh.T[:, rank:]
    # Orthonormalize columns (Vh from SVD already orthonormal)
    return Q

def kkt_nnls_pairs(c, r, tol=TOL_EQ):
    # Build Jacobian rows for active constraints at tol
    if ac_active_sets is not None:
        b_act, p_act = ac_active_sets(c, r, tol=tol)
        b_rows = [(int(i), str(kind)) for (i, kind, *_ ) in b_act]
        p_rows = [(int(i), int(j)) for (i, j, *_ ) in p_act]
    else:
        (s_xL, s_xR, s_yB, s_yT), sp = slacks(c, r)
        b_rows = []
        for i in range(N):
            if s_xL[i] <= tol: b_rows.append((i,'xL'))
            if s_xR[i] <= tol: b_rows.append((i,'xR'))
            if s_yB[i] <= tol: b_rows.append((i,'yB'))
            if s_yT[i] <= tol: b_rows.append((i,'yT'))
        p_rows = []
        for i in range(N):
            for j in range(i+1, N):
                if sp[i,j] <= tol:
                    p_rows.append((i,j))
    rows = []; ids = []
    for (i, kind) in b_rows:
        rows.append(grad_row_boundary(i, kind)); ids.append(('b', i, kind))
    for (i, j) in p_rows:
        rows.append(grad_row_pair(c, i, j));    ids.append(('p', i, j))
    if not rows:
        return {}, []
    J = np.vstack(rows)            # (M, 3N)
    A = J.T                        # (3N, M)
    b = np.zeros(3*N, dtype=float) # -∇f = e_r
    b[2::3] = 1.0
    if nnls is not None:
        lam, _ = nnls(A, b)
    else:
        lam = np.linalg.lstsq(A, b, rcond=None)[0]
        lam = np.maximum(lam, 0.0)
    lam_pairs = {}
    for idx, tag in enumerate(ids):
        if tag[0] == 'p':
            lam_pairs[(tag[1], tag[2])] = float(lam[idx])
    return lam_pairs, p_rows

def load_consensus_support():
    if not os.path.exists(P_CONS):
        return {}
    try:
        data = json.load(open(P_CONS, 'r'))
    except Exception:
        return {}
    supp = {}
    try:
        variants = data.get('variants', {})
        top_by_support = variants.get('pairs_top_by_support', []) or []
        for entry in top_by_support:
            pair, count = entry
            i, j = int(pair[0]), int(pair[1])
            supp[(min(i,j), max(i,j))] = int(count)
    except Exception:
        pass
    return supp

def select_hinges(c, r, k=5):
    # Composite: small slack (1e-8), lambda at 1e-8 if active, support count; interior encouraged
    (_, _ , _, _), sp = slacks(c, r)
    iu = np.triu_indices(N, 1)
    pairs_all = [(int(iu[0][idx]), int(iu[1][idx]), float(sp[iu][idx])) for idx in range(len(iu[0]))]
    pairs_all.sort(key=lambda t: t[2])  # asc by slack
    lam_pairs, _ = kkt_nnls_pairs(c, r, tol=TOL_EQ)
    support = load_consensus_support()

    bmask_1e9 = boundary_mask(c, r, tol=1e-9)
    bmask_1e8 = boundary_mask(c, r, tol=1e-8)

    scored = []
    for (i, j, s) in pairs_all[:200]:  # focus on near-active region
        lam = lam_pairs.get((i,j), lam_pairs.get((j,i), 0.0))
        supp = float(support.get((min(i,j), max(i,j)), 0))
        pen = 0.0
        if bmask_1e9[i] or bmask_1e9[j]: pen += 0.5  # penalize boundary adjacency at tighter tol
        # Score: higher better; mix inverse slack, lambda, support, minus penalty
        score = (1.0 / (1e-12 + s)) + 0.6*lam + 0.2*supp - pen
        # Must be interior at tol=1e-8 (encouraged manifold)
        if bmask_1e8[i] or bmask_1e8[j]:
            continue
        scored.append((score, i, j, s, lam, supp))
    scored.sort(key=lambda x: x[0], reverse=True)

    # ensure disc diversity
    chosen = []
    used = set()
    for (score, i, j, s, lam, supp) in scored:
        if i in used or j in used:
            continue
        chosen.append({'i': i, 'j': j, 'slack': s, 'lambda': lam, 'support': supp, 'score': float(score)})
        used.add(i); used.add(j)
        if len(chosen) >= k:
            break
    return chosen

def write_log(obj):
    os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
    with open(LOG_PATH, 'w') as f:
        json.dump(obj, f, indent=2)

# ------------- Main -------------
def construct_packing():
    c0, r0 = load_snapshot()
    base_sum = float(np.sum(r0))

    # Preconditions
    if polish_preserving_boundary is None:
        write_log({'error': 'missing_polisher', 'baseline_sum': base_sum})
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)

    # Boundary-equality tangent
    Aeq = build_Aeq_boundary(c0, r0, tol=TOL_EQ)
    Q = nullspace(Aeq, rtol=1e-10)  # (3N, k)
    if Q.shape[1] == 0:
        write_log({'error': 'zero_nullspace', 'Aeq_shape': Aeq.shape, 'baseline_sum': base_sum})
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)

    hinges = select_hinges(c0, r0, k=5)
    # Build linearized objective direction in Q-space: minimize sum of hinge slacks
    GQ_rows = []
    for h in hinges:
        i, j = h['i'], h['j']
        g = grad_row_pair(c0, i, j)
        GQ_rows.append(g @ Q)  # 1 x k
    if not GQ_rows:
        write_log({'error': 'no_hinges', 'baseline_sum': base_sum})
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)
    GQ = np.vstack(GQ_rows)  # (m, k)
    w = np.ones((GQ.shape[0],), dtype=float)
    v = (GQ.T @ w)  # gradient of summed slacks wrt u
    norm_v = float(np.linalg.norm(v))
    if norm_v < 1e-18:
        write_log({'error': 'flat_direction', 'baseline_sum': base_sum, 'hinges': hinges})
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)
    u_dir = -v / norm_v

    # Safety check on predicted changes for small-slack pairs
    (_, _ , _, _), sp = slacks(c0, r0)
    iu = np.triu_indices(N, 1)
    pairs_all = [(int(iu[0][k]), int(iu[1][k]), float(sp[iu][k])) for k in range(len(iu[0]))]
    pairs_all.sort(key=lambda t: t[2])
    tight_pairs = pairs_all[:40]  # check the 40 tightest pairs globally

    def predict_delta(u_scale):
        deltas = []
        for (i, j, s) in tight_pairs:
            g = grad_row_pair(c0, i, j)
            d = float((g @ Q) @ (u_scale * u_dir))
            deltas.append((i, j, s, d))
        return deltas

    # Line search on trust radius
    tau = 2.0e-3
    beta = 0.3  # allow up to 30% of current slack reduction in linearized prediction
    ok = False; u_use = None
    for _ in range(10):
        deltas = predict_delta(tau)
        viol = False
        for (_, _, s, d) in deltas:
            if d < -beta * s:
                viol = True; break
        if not viol:
            ok = True; u_use = tau * u_dir; break
        tau *= 0.5
    if not ok:
        write_log({'error': 'trust_region_failed', 'baseline_sum': base_sum, 'last_tau': tau, 'hinges': hinges})
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)

    # Apply tangent step
    z0 = pack_to_z(c0, r0)
    dz = Q @ u_use
    z_seed = z0 + dz
    c_seed, r_seed = z_to_pack(z_seed)
    c_seed = np.clip(c_seed, 0.0, 1.0)

    # Equality-constrained polish preserving boundary
    c_opt, r_opt = polish_preserving_boundary(c_seed, r_seed, tol_eq=TOL_EQ, step_c=1e-3, step_r=1e-3, maxiter=600)
    # Final tiny shrink for robust evaluation
    r_opt = np.maximum(r_opt - SAFETY, R_MIN)

    sum_opt = float(np.sum(r_opt))
    delta_sum = sum_opt - base_sum

    # Diagnostics: compute pair-set Jaccard at tol=1e-8
    def pair_set(c, r, tol=TOL_EQ):
        if ac_active_sets is not None:
            _, p_act = ac_active_sets(c, r, tol=tol)
            return set((min(int(i), int(j)), max(int(i), int(j))) for (i, j, *_ ) in p_act)
        else:
            (_, _ , _, _), sp2 = slacks(c, r)
            ps = set()
            for i in range(N):
                for j in range(i+1, N):
                    if sp2[i,j] <= tol:
                        ps.add((i,j))
            return ps

    pairs_base = pair_set(c0, r0, tol=TOL_EQ)
    pairs_cand = pair_set(c_opt, r_opt, tol=TOL_EQ)
    inter = len(pairs_base & pairs_cand); uni = len(pairs_base | pairs_cand)
    j_pairs = (inter / uni) if uni > 0 else 1.0

    # Predicted vs realized hinge deltas (post-polish)
    post_slacks = {}
    (_, _ , _, _), sp_after = slacks(c_opt, r_opt)
    for h in hinges:
        i, j = h['i'], h['j']
        s0 = float(sp[min(i,j), max(i,j)] if i<j else sp[max(i,j), min(i,j)])
        s1 = float(sp_after[min(i,j), max(i,j)] if i<j else sp_after[max(i,j), min(i,j)])
        h['slack_before'] = s0
        h['slack_after']  = s1
        h['delta_slack']  = s1 - s0

    # Log
    log = {
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'Aeq_shape': list(Aeq.shape),
        'nullspace_dim': int(Q.shape[1]),
        'tau_used': float(np.linalg.norm(u_use)),
        'baseline_sum': base_sum,
        'candidate_sum': sum_opt,
        'delta_sum': delta_sum,
        'pair_jaccard_vs_baseline': j_pairs,
        'hinges': hinges
    }
    try:
        write_log(log)
    except Exception:
        pass

    # Return better of baseline vs candidate (respecting guardrail)
    if delta_sum >= 1e-12:
        return c_opt.astype(float), r_opt.astype(float)
    else:
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)
